// ChunkKind — Rodzaj fragmentu strumienia; wspolny dla wszystkich kanalow. Ten sam slownik opisuje rodzaj tresci wiadomosci zapisanej w bazie
type ChunkKind string

// Wartosci ChunkKind.
const (
	// Tekst odpowiedzi
	ChunkKindText = "text"
	// Tok rozumowania
	ChunkKindThinking = "thinking"
	// Wywolanie narzedzia
	ChunkKindToolUse = "tool_use"
	// Wynik narzedzia
	ChunkKindToolResult = "tool_result"
	// Tresc obrazowa
	ChunkKindImage = "image"
	// Tresc dzwiekowa
	ChunkKindAudio = "audio"
	// Blad w trakcie strumienia
	ChunkKindError = "error"
	// Prowenancja wywolania: argv, prompt systemowy, ustawienia, skrot
	ChunkKindProvenance = "provenance"
	// Metadane konta kanalu glownego przy rotacji
	ChunkKindAccount = "account"
	// Wersja OSTATECZNA odpowiedzi. ZASTEPUJE tresc zlozona z dotychczasowych fragmentow tekstowych, nie doklada sie do niej. Niesie ja koperta domykajaca (done=true); odbiorca podmienia tekst wpisu na tresc tego fragmentu. Wartosc PRZELOTOWA — tresc ostateczna utrwala sie jako `content` wiadomosci o rodzaju `tekst`, wiec sam ten rodzaj do kolumny nigdy nie trafia
	ChunkKindFinal = "final"
)

// WartosciChunkKind zwraca komplet wartosci ChunkKind w kolejnosci kontraktu.
func WartosciChunkKind() []ChunkKind {
	return []ChunkKind{
		ChunkKindText,
		ChunkKindThinking,
		ChunkKindToolUse,
		ChunkKindToolResult,
		ChunkKindImage,
		ChunkKindAudio,
		ChunkKindError,
		ChunkKindProvenance,
		ChunkKindAccount,
		ChunkKindFinal,
	}
}

